using System;using System.IO;using System.Diagnostics;using System.Windows.Forms;using System.Reflection;
class Entry { [STAThread] static void Main(){try {string dir=Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location);string python=Path.GetFullPath(Path.Combine(dir,"..","OverFieldLauncher-portable","runtime-python","python.exe"));if(!File.Exists(python))throw new Exception("请将单机修复与管理放在 OverFieldLauncher-portable 旁边。");Process.Start(new ProcessStartInfo {FileName=python,Arguments="-X utf8 \""+Path.Combine(dir,"manager.py")+"\" --open",WorkingDirectory=dir,UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden});}catch(Exception e){MessageBox.Show(e.Message,"开放空间单机管理");}}}
